Turns out there are more examples that exhibit the same behaviour, e.g. `mask = pl.col("a") == pl.lit(0)`.

I noticed these writing some hypothesis tests to compare the GPU engine parquet filtering to polars:

```python
import hypothesis.strategies as st
from hypothesis import given, settings

from polars.testing import assert_frame_equal
import pytest

import polars as pl


@pytest.fixture(scope="module")
def df():
    return pl.DataFrame(
        {
            "a": [1, 2, 3, None, 4, 5],
            "b": [None, None, 3, None, 4, 0],
        }
    )


@st.composite
def integer_literal(draw):
    return pl.lit(draw(st.integers(min_value=-1, max_value=8)), dtype=pl.Int64)


@st.composite
def null_literal(draw):
    return pl.lit(draw(st.none()), dtype=pl.Int64)


literal = st.one_of(null_literal(), integer_literal())


@st.composite
def column(draw):
    return pl.col(draw(st.sampled_from(["a", "b"])))


columns = column()

value = st.one_of(integer_literal(), columns)

math_binop = st.sampled_from([pl.Expr.add, pl.Expr.sub, pl.Expr.mul])


@st.composite
def math_expr(draw):
    op = draw(math_binop)
    lop = draw(columns)
    rop = draw(value)
    return op(lop, rop)


boolean_binop = st.sampled_from(
    [
        pl.Expr.eq,
        pl.Expr.eq_missing,
        pl.Expr.ne,
        pl.Expr.ne_missing,
        pl.Expr.lt,
        pl.Expr.le,
        pl.Expr.gt,
        pl.Expr.ge,
    ]
)


@st.composite
def bool_expr(draw):
    op = draw(boolean_binop)
    exprs = st.one_of(math_expr(), literal)
    lop = draw(math_expr())
    rop = draw(exprs)
    return op(lop, rop)


@st.composite
def combine(draw, children):
    op = draw(st.sampled_from([pl.Expr.and_, pl.Expr.or_]))
    return op(draw(children), draw(children))


filter = st.recursive(bool_expr(), lambda children: combine(children), max_leaves=2)


@pytest.fixture(scope="module")
def pq_file(tmp_path_factory, df):
    tmp_path = tmp_path_factory.mktemp("parquet_filter")
    df.write_parquet(tmp_path / "tmp.pq", row_group_size=3)
    return pl.scan_parquet(tmp_path / "tmp.pq")


@given(expr=filter)
@settings(deadline=2000, print_blob=True)
def test_scan(expr, pq_file):
    df = pq_file.collect()
    q = pq_file.filter(expr)

    assert_frame_equal(q.collect(), df.filter(expr))
```
